  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_medical_item_code` (`item_code`),
  CONSTRAINT `ck_medical_item_price` CHECK ((`unit_price` >= 0)),
  CONSTRAINT `ck_medical_item_stock` CHECK (((`stock_quantity` is null) or (`stock_quantity` >= 0))),
  CONSTRAINT `ck_medical_item_type` CHECK ((`item_type` in (_utf8mb4'DRUG',_utf8mb4'EXAMINATION',_utf8mb4'TREATMENT',_utf8mb4'BED_FEE')))
