CREATE TABLE `medical_order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) NOT NULL,
  `admission_id` bigint NOT NULL,
  `order_type` varchar(20) NOT NULL,
  `frequency` varchar(32) DEFAULT NULL,
  `status` varchar(24) NOT NULL DEFAULT 'DRAFT',
  `start_time` timestamp(3) NULL DEFAULT NULL,
  `planned_end_time` timestamp(3) NULL DEFAULT NULL,
  `submitted_at` timestamp(3) NULL DEFAULT NULL,
  `stopped_at` timestamp(3) NULL DEFAULT NULL,
  `note` varchar(500) DEFAULT NULL,
  `prescribed_by` bigint NOT NULL,
  `created_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_medical_order_no` (`order_no`),
  KEY `idx_order_admission_status` (`admission_id`,`status`),
  KEY `idx_order_prescriber_time` (`prescribed_by`,`created_at`),
  CONSTRAINT `fk_order_admission` FOREIGN KEY (`admission_id`) REFERENCES `admission` (`id`),
  CONSTRAINT `fk_order_prescriber` FOREIGN KEY (`prescribed_by`) REFERENCES `staff` (`id`),
  CONSTRAINT `ck_order_status` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'SUBMITTED',_utf8mb4'IN_PROGRESS',_utf8mb4'COMPLETED',_utf8mb4'STOPPED',_utf8mb4'CANCELLED'))),
  CONSTRAINT `ck_order_time` CHECK (((`planned_end_time` is null) or (`start_time` is null) or (`planned_end_time` >= `start_time`))),
  CONSTRAINT `ck_order_type` CHECK ((`order_type` in (_utf8mb4'TEMPORARY',_utf8mb4'LONG_TERM')))
