/*!50003 CREATE*/ /*!50017 DEFINER=`hospital_app`@`localhost`*/ /*!50003 TRIGGER `trg_order_admission_guard_insert` BEFORE INSERT ON `medical_order` FOR EACH ROW BEGIN
    IF NOT EXISTS (SELECT 1 FROM admission WHERE id = NEW.admission_id AND status = 'IN_HOSPITAL') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '只能为住院中的患者创建医嘱';
    END IF;
END */;;
DELIMITER ;
