CREATE DEFINER=`hospital_app`@`localhost` PROCEDURE `sp_admit_patient`(
    IN p_patient_id BIGINT,
    IN p_department_id BIGINT,
    IN p_doctor_id BIGINT,
    IN p_bed_id BIGINT,
    IN p_initial_deposit DECIMAL(12,2),
    IN p_operator_id BIGINT,
    OUT p_admission_id BIGINT
)
BEGIN
    DECLARE v_bed_status VARCHAR(20);
    DECLARE v_admission_no VARCHAR(32);

    SELECT status INTO v_bed_status FROM bed WHERE id = p_bed_id FOR UPDATE;
    IF v_bed_status IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '目标床位不存在';
    END IF;
    IF v_bed_status <> 'AVAILABLE' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '目标床位不是空闲状态';
    END IF;
    IF EXISTS (SELECT 1 FROM admission WHERE patient_id = p_patient_id AND status IN ('PENDING','IN_HOSPITAL','PENDING_DISCHARGE')) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '患者已有有效住院记录';
    END IF;

    SET v_admission_no = CONCAT('A', UUID_SHORT());
    INSERT INTO admission(admission_no, patient_id, department_id, attending_doctor_id, current_bed_id,
                          status, admission_time, created_by)
    VALUES(v_admission_no, p_patient_id, p_department_id, p_doctor_id, p_bed_id,
           'IN_HOSPITAL', UTC_TIMESTAMP(3), p_operator_id);
    SET p_admission_id = LAST_INSERT_ID();

    INSERT INTO bed_usage(admission_id, bed_id, start_time, assigned_by)
    VALUES(p_admission_id, p_bed_id, UTC_TIMESTAMP(3), p_operator_id);
    UPDATE bed SET status = 'OCCUPIED', version = version + 1 WHERE id = p_bed_id;

    IF p_initial_deposit > 0 THEN
        INSERT INTO deposit_transaction(admission_id, transaction_no, transaction_type, amount,
                                        payment_method, note, operated_by)
        VALUES(p_admission_id,
               CONCAT('D', UUID_SHORT()),
               'INITIAL', p_initial_deposit, 'CASH', '入院初始押金', p_operator_id);
    END IF;
END ;;
DELIMITER ;
