/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`hospital_app`@`localhost` PROCEDURE `sp_discharge_settlement`(
    IN p_admission_id BIGINT,
    IN p_operator_id BIGINT,
    OUT p_settlement_id BIGINT
)
BEGIN
    DECLARE v_status VARCHAR(24);
    DECLARE v_bed_id BIGINT;
    DECLARE v_total_charge DECIMAL(12,2);
    DECLARE v_total_deposit DECIMAL(12,2);
    DECLARE v_due DECIMAL(12,2);
    DECLARE v_refund DECIMAL(12,2);

    SELECT status, current_bed_id INTO v_status, v_bed_id
      FROM admission WHERE id = p_admission_id FOR UPDATE;
    IF v_status NOT IN ('IN_HOSPITAL','PENDING_DISCHARGE') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '当前住院状态不可结算';
    END IF;
    IF EXISTS (
        SELECT 1 FROM medical_order
         WHERE admission_id = p_admission_id AND status IN ('SUBMITTED','IN_PROGRESS')
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '仍有未完成医嘱，不能结算';
    END IF;
    IF EXISTS (SELECT 1 FROM settlement WHERE admission_id = p_admission_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '该次住院已经结算';
    END IF;

    SELECT total_charge INTO v_total_charge
      FROM v_admission_charge_summary WHERE admission_id = p_admission_id;
    SELECT deposit_balance INTO v_total_deposit
      FROM v_admission_deposit_balance WHERE admission_id = p_admission_id;
    SET v_due = GREATEST(v_total_charge - v_total_deposit, 0);
    SET v_refund = GREATEST(v_total_deposit - v_total_charge, 0);
    IF v_due > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '押金不足，请先补缴费用';
    END IF;

    INSERT INTO settlement(settlement_no, admission_id, total_charge, total_deposit,
                           amount_due, refund_amount, settled_by)
    VALUES(CONCAT('S', UUID_SHORT()),
           p_admission_id, v_total_charge, v_total_deposit, v_due, v_refund, p_operator_id);
    SET p_settlement_id = LAST_INSERT_ID();

    INSERT INTO settlement_detail(settlement_id, category, amount, item_count)
    SELECT p_settlement_id, mi.item_type, COALESCE(SUM(c.amount), 0), COUNT(c.id)
      FROM medical_item mi
      JOIN charge_detail c ON c.medical_item_id = mi.id
     WHERE c.admission_id = p_admission_id
     GROUP BY mi.item_type;

    IF v_refund > 0 THEN
        INSERT INTO deposit_transaction(admission_id, transaction_no, transaction_type, amount,
                                        payment_method, note, operated_by)
        VALUES(p_admission_id,
               CONCAT('D', UUID_SHORT()),
               'REFUND', -v_refund, 'CASH', '出院结算退款', p_operator_id);
    END IF;
    UPDATE bed_usage SET end_time = UTC_TIMESTAMP(3), end_reason = 'DISCHARGE'
     WHERE admission_id = p_admission_id AND end_time IS NULL;
    UPDATE bed SET status = 'AVAILABLE', version = version + 1 WHERE id = v_bed_id;
    UPDATE admission
       SET status = 'DISCHARGED', discharge_time = UTC_TIMESTAMP(3), current_bed_id = NULL, version = version + 1
     WHERE id = p_admission_id;
    UPDATE account_alert SET status = 'RESOLVED', resolved_by = p_operator_id, resolved_at = UTC_TIMESTAMP(3)
     WHERE admission_id = p_admission_id AND status = 'OPEN';
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_execute_order` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`hospital_app`@`localhost` PROCEDURE `sp_execute_order`(
    IN p_order_item_id BIGINT,
    IN p_request_no VARCHAR(64),
    IN p_executor_id BIGINT,
    IN p_quantity DECIMAL(12,3),
    IN p_operator_user_id BIGINT,
    IN p_alert_threshold DECIMAL(12,2),
    OUT p_execution_id BIGINT
)
BEGIN
    DECLARE v_order_id BIGINT;
    DECLARE v_admission_id BIGINT;
    DECLARE v_order_status VARCHAR(24);
    DECLARE v_admission_status VARCHAR(24);
    DECLARE v_item_id BIGINT;
    DECLARE v_item_type VARCHAR(20);
    DECLARE v_unit_price DECIMAL(12,2);
    DECLARE v_stock DECIMAL(12,3);
    DECLARE v_balance DECIMAL(12,2);

    IF EXISTS (SELECT 1 FROM execution_record WHERE request_no = p_request_no) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '该执行请求已处理';
    END IF;
    SELECT oi.medical_order_id, mo.admission_id, mo.status, a.status, oi.medical_item_id
      INTO v_order_id, v_admission_id, v_order_status, v_admission_status, v_item_id
      FROM order_item oi
      JOIN medical_order mo ON mo.id = oi.medical_order_id
      JOIN admission a ON a.id = mo.admission_id
     WHERE oi.id = p_order_item_id FOR UPDATE;
    IF v_order_status NOT IN ('SUBMITTED','IN_PROGRESS') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '医嘱当前状态不可执行';
    END IF;
    IF v_admission_status <> 'IN_HOSPITAL' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '患者当前不在院';
    END IF;

    SELECT item_type, unit_price, stock_quantity
      INTO v_item_type, v_unit_price, v_stock
      FROM medical_item WHERE id = v_item_id FOR UPDATE;
    IF v_item_type = 'DRUG' AND (v_stock IS NULL OR v_stock < p_quantity) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '药品库存不足，执行已回滚';
    END IF;

    INSERT INTO execution_record(request_no, order_item_id, quantity, status, result_note, executor_id)
    VALUES(p_request_no, p_order_item_id, p_quantity, 'SUCCESS', '执行成功', p_executor_id);
    SET p_execution_id = LAST_INSERT_ID();

    IF v_item_type = 'DRUG' THEN
        UPDATE medical_item
           SET stock_quantity = stock_quantity - p_quantity, version = version + 1
         WHERE id = v_item_id;
        INSERT INTO drug_inventory_transaction(medical_item_id, execution_id, transaction_type,
                                               quantity, before_quantity, after_quantity, note, operated_by)
        VALUES(v_item_id, p_execution_id, 'DISPENSE', -p_quantity, v_stock, v_stock - p_quantity,
               '医嘱执行自动扣减', p_operator_user_id);
    END IF;

    INSERT INTO charge_detail(admission_id, execution_id, medical_item_id, charge_no, charge_type,
                              unit_price_snapshot, quantity, amount, note)
    VALUES(v_admission_id, p_execution_id, v_item_id,
           CONCAT('C', UUID_SHORT()),
           'NORMAL', v_unit_price, p_quantity, ROUND(v_unit_price * p_quantity, 2), '医嘱执行自动计费');
    UPDATE order_item SET executed_quantity = executed_quantity + p_quantity WHERE id = p_order_item_id;
    UPDATE medical_order SET status = 'IN_PROGRESS' WHERE id = v_order_id AND status = 'SUBMITTED';

    SELECT available_balance INTO v_balance
      FROM v_admission_deposit_balance WHERE admission_id = v_admission_id;
    IF v_balance < p_alert_threshold
       AND NOT EXISTS (SELECT 1 FROM account_alert WHERE admission_id = v_admission_id AND status = 'OPEN') THEN
        INSERT INTO account_alert(admission_id, level, balance_snapshot, threshold_snapshot)
        VALUES(v_admission_id, IF(v_balance < 0, 'CRITICAL', 'WARNING'), v_balance, p_alert_threshold);
    END IF;
END ;;
DELIMITER ;
