CREATE DEFINER=`hospital_app`@`localhost` PROCEDURE `sp_transfer_bed`(
    IN p_admission_id BIGINT,
    IN p_target_bed_id BIGINT,
    IN p_reason VARCHAR(500),
    IN p_operator_id BIGINT
)
BEGIN
    DECLARE v_status VARCHAR(24);
    DECLARE v_old_bed_id BIGINT;
    DECLARE v_target_status VARCHAR(20);
    DECLARE v_department_id BIGINT;
    DECLARE v_doctor_id BIGINT;

    SELECT status, current_bed_id, department_id, attending_doctor_id
      INTO v_status, v_old_bed_id, v_department_id, v_doctor_id
      FROM admission WHERE id = p_admission_id FOR UPDATE;
    IF v_status <> 'IN_HOSPITAL' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '仅住院中的患者可以转床';
    END IF;
    SELECT status INTO v_target_status FROM bed WHERE id = p_target_bed_id FOR UPDATE;
    IF v_target_status <> 'AVAILABLE' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '目标床位不可用';
    END IF;
    IF v_old_bed_id = p_target_bed_id THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '目标床位与当前床位相同';
    END IF;

    UPDATE bed_usage
       SET end_time = UTC_TIMESTAMP(3), end_reason = 'TRANSFER'
     WHERE admission_id = p_admission_id AND end_time IS NULL;
    INSERT INTO bed_usage(admission_id, bed_id, start_time, assigned_by)
    VALUES(p_admission_id, p_target_bed_id, UTC_TIMESTAMP(3), p_operator_id);
    UPDATE bed SET status = 'AVAILABLE', version = version + 1 WHERE id = v_old_bed_id;
    UPDATE bed SET status = 'OCCUPIED', version = version + 1 WHERE id = p_target_bed_id;
    UPDATE admission SET current_bed_id = p_target_bed_id, version = version + 1 WHERE id = p_admission_id;
    INSERT INTO transfer_record(admission_id, transfer_type, from_department_id, to_department_id,
                                from_bed_id, to_bed_id, from_doctor_id, to_doctor_id, reason, operated_by)
    VALUES(p_admission_id, 'BED', v_department_id, v_department_id, v_old_bed_id, p_target_bed_id,
           v_doctor_id, v_doctor_id, p_reason, p_operator_id);
END ;;
DELIMITER ;
